using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S1.Digit.Infinite;

internal sealed class ResetCodebookWeightedDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S1/Digit/Infinite/ResetCodebookWeighted.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Analytic/mathlib2026gelfandandivt");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Reset codebooks, actual sources and weighted lower-memory graphs.",
        H("Reset codebook: Weighted"),
        Blocks(
            Node("weight_cons", "weight cons", "For the specified parameters, the following hypotheses imply the stated relation: (a : D5.S1.Digit.Infinite.ResetCodebook.Return) (as : List D5.S1.Digit.Infinite.ResetCodebook.Return) : D5.S1.Digit.Infinite.ResetCodebook.Statement.weight (a::as) = (6*a.val.1 + 20*a.val.2) + D5.S1.Digit.Infinite.ResetCodebook.Statement.weight as", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("codebook_finite", "codebook finite", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (K N : ℕ) (d : ℝ) : (D5.S1.Digit.Infinite.ResetCodebook.Statement.codebook anchor K N d).Finite", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("boolWeight_pos", "boolWeight pos", "For the specified parameters, the following hypotheses imply the stated relation: (c : Bool) : 0 < (if c then 20 else 6 : ℕ)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("letterWeight_append", "letterWeight append", "For the specified parameters, the following hypotheses imply the stated relation: (u v : List Bool) : D5.S1.Digit.Infinite.ResetCodebook.Statement.letterWeight (u ++ v) = D5.S1.Digit.Infinite.ResetCodebook.Statement.letterWeight u + D5.S1.Digit.Infinite.ResetCodebook.Statement.letterWeight v", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("weighted_prefix_free", "weighted prefix free", "For the specified parameters, the following hypotheses imply the stated relation: (N : ℕ) (S : Set (List Bool)) (hweight : ∀ w ∈ S, D5.S1.Digit.Infinite.ResetCodebook.Statement.letterWeight w = N) : IsPrefixFree S", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("codeword_weight", "codeword weight", "For the specified parameters, the following hypotheses imply the stated relation: (as : List D5.S1.Digit.Infinite.ResetCodebook.Return) : D5.S1.Digit.Infinite.ResetCodebook.Statement.letterWeight (D5.S1.Digit.Infinite.ResetCodebook.Statement.letters as) = D5.S1.Digit.Infinite.ResetCodebook.Statement.weight as", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("letter_length_le_weight", "letter length le weight", "For the specified parameters, the following hypotheses imply the stated relation: (w : List Bool) : w.length ≤ Statement.letterWeight w", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("weighted_factor_count", "weighted factor count", "For the specified parameters, the following hypotheses imply the stated relation: (V : Set (List Bool)) (lang : Set (ℤ → Bool)) (L : ℕ) (hV : V.Finite) (hL : 0 < L) (hweight : ∀ w∈V, Statement.letterWeight w=L) (hext : ∀ (k : ℕ) (f : Fin k → Words V), ∃ omega∈lang, Statement.factor (List.ofFn (fun i => (f i).val)).flatten omega) (k : ℕ) : (Nat.card (Words V))^k ≤ Statement.factorCount lang (k*L)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("reset_codeword_weight", "reset codeword weight", "For the specified parameters, the following hypotheses imply the stated relation: (M : ℕ) (hM : 1 ≤ M) (v : List Return) : Statement.letterWeight (Statement.letters (Statement.reset M hM::v)) = 20+6*M+Statement.weight v", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("leading", "leading", "The mathematical data are specified by leading(b : Bool) : List Bool → ℕ | [] => 0 | c::cs => if c=b then leading b cs+1 else 0 private lemma leading_replicate (b : Bool) (n : ℕ) (w : List Bool) : leading b (List.replicate n b++w) = n+leading b w := by.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("resetImage", "resetImage", "The mathematical data are specified by resetImage(anchor : Bool) (K M N : ℕ) (d : ℝ) (hM : 1≤M) : Set (List Bool) := .", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("resetBookEquiv", "resetBookEquiv", "The mathematical data are specified by resetBookEquiv(anchor : Bool) (K M N : ℕ) (d : ℝ) (hM : 1≤M) : WeakBook anchor K N d ≃ Words (resetImage anchor K M N d hM) := by.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("weak_book_factor_count", "weak book factor count", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (K M N : ℕ) (d : ℝ) (hM : 1≤M) (lang : Set (ℤ → Bool)) (hext : ∀ (k : ℕ) (f : Fin k → Words (resetImage anchor K M N d hM)), ∃ omega∈lang, Statement.factor (List.ofFn (fun i => (f i).val)).flatten omega) (k : ℕ) : (Nat.card (WeakBook anchor K N d))^k ≤ Statement.factorCount lang (k*(N+20+6*M))", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("weightedReadout", "weightedReadout", "The mathematical data are specified by weightedReadout(lang : Set (ℤ → Bool)) (n : ℕ) : ℝ := .", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("weighted_rate_from_counts", "weighted rate from counts", "For the specified parameters, the following hypotheses imply the stated relation: (lang : Set (ℤ → Bool)) (a L : ℕ) (ha : 0<a) (hL : 0<L) (hc : ∀ k, a^k ≤ Statement.factorCount lang (k*L)) (hb : Filter.IsBoundedUnder (· ≤ ·) Filter.atTop (weightedReadout lang)) : Real.log (a:ℝ)/Real.log 2/(L:ℝ) ≤ Statement.rate lang", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("weightedReadout_bounded", "weightedReadout bounded", "For the specified parameters, the following hypotheses imply the stated relation: (lang : Set (ℤ → Bool)) : Filter.IsBoundedUnder (· ≤ ·) Filter.atTop (weightedReadout lang)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("weak_book_language_rate", "weak book language rate", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (K M N : ℕ) (d : ℝ) (hM : 1≤M) (hne : (Statement.codebook anchor K N d).Nonempty) (lang : Set (ℤ → Bool)) (hext : ∀ (k : ℕ) (f : Fin k → Words (resetImage anchor K M N d hM)), ∃ omega∈lang, Statement.factor (List.ofFn (fun i => (f i).val)).flatten omega) : Real.log (Nat.card (WeakBook anchor K N d):ℝ)/Real.log 2/(N+20+6*M:ℝ) ≤ Statement.rate lang", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("periodicWord", "periodicWord", "The mathematical data are specified by periodicWord(u : List Bool) (i : ℤ) : Bool := .", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("periodic_reset_word_membership", "periodic reset word membership", "Every finite list of reset codewords extends to a bilateral periodic reset concatenation. The same extension contains the flattened finite word as a factor and belongs to the fixed strict lower-memory language whenever its truncation error is below the common state margin.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("complete_lower_language_count_and_rate", "complete lower language count and rate", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (K M N n : ℕ) (d : ℝ) (hK : 2 ≤ K) (hM : 1 ≤ M) (hreset : initial false anchor < Statement.B M) (hcut : h false*rho^n < chi^(K-1)*(Statement.B M-initial false anchor)*g^N) (hne : (Statement.codebook anchor K N d).Nonempty) : (∀ k, (Nat.card (WeakBook anchor K N d))^k ≤ Statement.factorCount (Statement.lowerLanguage K n d) (k*(N+20+6*M))) ∧ Real.log (Nat.card (WeakBook anchor K N d):ℝ)/Real.log 2/(N+20+6*M:ℝ) ≤ Statement.rate (Statement.lowerLanguage K n d)", DescribeRole.Theorem, AssessedProvenance.FromRepo())
        )));

    private static DocumentBlock Node(string declaration, string title, string prose,
        DescribeRole role, AssessedProvenance provenance) =>
        Describe.Lean(DescribeId.Create("resetcodebookweighted-" + declaration.ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + declaration), H(title),
            StatementSource.WithoutFormula(), provenance,
            Blocks(Paragraph(Text(prose))), role);
}
